sys_ux_client_script.script:
function evaluateProperty({
    api,
    helpers
}) {
    var rawRoi = api.context.props.fields.year_one_net_roi.value;
    if (!rawRoi) {
        return 70;
    }
    var roi = parseFloat(rawRoi) || 0;
    var xAxisValue = 50 + ((roi / 100000) * 50);
    return Math.max(0, Math.min(100, xAxisValue));
}
